-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the porepressure capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- porepressure / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'porepressure' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book porepressure refused: porepressure/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '53381b4dd3b1eebd22babc3434f85545' and fields = '[{"key": "hydro_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Hydrostatic pressure at TD", "expected": 41.408579625}, {"key": "ob_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overburden stress at TD", "expected": 91.12306695073282}, {"key": "gardner_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gardner density at 1600 m/s", "expected": 1960.612149304395}, {"key": "nct_2500", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at 2500 m", "expected": 317.2847498247154}, {"key": "fit_dtml", "tol": 0.5, "unit": "us/m", "label": "Fitted NCT mudline transit time", "expected": 650.0000000000014}, {"key": "fit_c_per_km", "tol": 0.005, "unit": "1/km", "label": "Fitted compaction constant", "expected": 0.7000000000000015}]'::jsonb then 'old'
              when md5(prompt) = '5a54f1b778a0fd58ee037e651fc66ee6' and fields = '[{"key": "hydro_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Hydrostatic pressure at TD", "expected": 41.408579625}, {"key": "ob_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overburden stress at TD", "expected": 91.12306695073282}, {"key": "gardner_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gardner density at 1600 m/s", "expected": 1960.612149304395}, {"key": "nct_2500", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at 2500 m", "expected": 317.2847498247154}, {"key": "fit_dtml", "tol": 0.5, "unit": "us/m", "label": "Fitted NCT mudline transit time", "expected": 650.0000000000014}, {"key": "fit_c_per_km", "tol": 0.005, "unit": "1/km", "label": "Fitted compaction constant", "expected": 0.7000000000000015}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'porepressure' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book porepressure refused: porepressure/beginner matches neither its published form (prompt md5 53381b4dd3b1eebd22babc3434f85545) nor its W1 form (prompt md5 5a54f1b778a0fd58ee037e651fc66ee6), with the fields this file was generated against';
  end if;

  -- porepressure / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'porepressure' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book porepressure refused: porepressure/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '6adc47b533f50ea3f48f60fc79f6fdfc' and fields = '[{"key": "onset_m", "tol": 0, "unit": "m bml", "label": "Overpressure onset depth", "expected": 2520}, {"key": "dtn_td", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at TD", "expected": 259.5530276341839}, {"key": "pp_3000_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at 3000 m", "expected": 33.307730125}, {"key": "pp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD", "expected": 47.408579625}, {"key": "op_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overpressure at TD", "expected": 6}, {"key": "fp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Fracture pressure at TD", "expected": 76.55157117548856}]'::jsonb then 'old'
              when md5(prompt) = 'd3429a6bfebb24bbf86b33d7acaea0bd' and fields = '[{"key": "onset_m", "tol": 0, "unit": "m bml", "label": "Overpressure onset depth", "expected": 2520}, {"key": "dtn_td", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at TD", "expected": 259.5530276341839}, {"key": "pp_3000_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at 3000 m", "expected": 33.307730125}, {"key": "pp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD", "expected": 47.408579625}, {"key": "op_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overpressure at TD", "expected": 6}, {"key": "fp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Fracture pressure at TD", "expected": 76.55157117548856}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'porepressure' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book porepressure refused: porepressure/intermediate matches neither its published form (prompt md5 6adc47b533f50ea3f48f60fc79f6fdfc) nor its W1 form (prompt md5 d3429a6bfebb24bbf86b33d7acaea0bd), with the fields this file was generated against';
  end if;

  -- porepressure / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'porepressure' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book porepressure refused: porepressure/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '68a252dc2068c233dedcee3850245256' and fields = '[{"key": "pp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Pore pressure as EMW at TD", "expected": 1179.1048116553065}, {"key": "fp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Fracture pressure as EMW at TD", "expected": 1903.9238599165737}, {"key": "window_td", "tol": 0.5, "unit": "kg/m3", "label": "Mud-weight window at TD", "expected": 724.8190482612672}, {"key": "bowers_v_5mpa", "tol": 0.5, "unit": "m/s", "label": "Bowers loading velocity at 5 MPa", "expected": 1949.944709834568}, {"key": "bowers_sigma_mpa", "tol": 0.01, "unit": "MPa", "label": "Bowers unloading stress at 3125.8 m/s", "expected": 10}, {"key": "pp_td_n12_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD with n = 1.2", "expected": 43.901549937778526}]'::jsonb then 'old'
              when md5(prompt) = '4e6a35b11d2f999b38595707bcead8dc' and fields = '[{"key": "pp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Pore pressure as EMW at TD", "expected": 1179.1048116553065}, {"key": "fp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Fracture pressure as EMW at TD", "expected": 1903.9238599165737}, {"key": "window_td", "tol": 0.5, "unit": "kg/m3", "label": "Mud-weight window at TD", "expected": 724.8190482612672}, {"key": "bowers_v_5mpa", "tol": 0.5, "unit": "m/s", "label": "Bowers loading velocity at 5 MPa", "expected": 1949.944709834568}, {"key": "bowers_sigma_mpa", "tol": 0.01, "unit": "MPa", "label": "Bowers unloading stress at 3125.8 m/s", "expected": 10}, {"key": "pp_td_n12_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD with n = 1.2", "expected": 43.901549937778526}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'porepressure' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book porepressure refused: porepressure/advanced matches neither its published form (prompt md5 68a252dc2068c233dedcee3850245256) nor its W1 form (prompt md5 4e6a35b11d2f999b38595707bcead8dc), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book porepressure: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book porepressure refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Build the frame on the golden well (4000 m below mudline, 100 m water, seawater 1025 kg/m3, pore fluid 1030 kg/m3): hydrostatic and overburden at TD, the Gardner density a sonic-only interval would use at 1600 m/s, the normal-compaction transit time at 2500 m on the well''s trend (656/220/0.0006), and the exact least-squares NCT fit through the twelve shale picks (matrix dt 220 us/m).',
           fields = '[{"key": "hydro_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Hydrostatic pressure at TD", "expected": 41.408579625}, {"key": "ob_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overburden stress at TD", "expected": 91.12306695073282}, {"key": "gardner_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gardner density at 1600 m/s", "expected": 1960.612149304395}, {"key": "nct_2500", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at 2500 m", "expected": 317.2847498247154}, {"key": "fit_dtml", "tol": 0.5, "unit": "us/m", "label": "Fitted NCT mudline transit time", "expected": 650.0000000000014}, {"key": "fit_c_per_km", "tol": 0.005, "unit": "1/km", "label": "Fitted compaction constant", "expected": 0.7000000000000015}]'::jsonb
     where app_slug = 'porepressure' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book porepressure refused: porepressure/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '5a54f1b778a0fd58ee037e651fc66ee6' and fields = '[{"key": "hydro_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Hydrostatic pressure at TD", "expected": 41.408579625}, {"key": "ob_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overburden stress at TD", "expected": 91.12306695073282}, {"key": "gardner_rho", "tol": 0.5, "unit": "kg/m3", "label": "Gardner density at 1600 m/s", "expected": 1960.612149304395}, {"key": "nct_2500", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at 2500 m", "expected": 317.2847498247154}, {"key": "fit_dtml", "tol": 0.5, "unit": "us/m", "label": "Fitted NCT mudline transit time", "expected": 650.0000000000014}, {"key": "fit_c_per_km", "tol": 0.005, "unit": "1/km", "label": "Fitted compaction constant", "expected": 0.7000000000000015}]'::jsonb) from public.academy_capstones where app_slug = 'porepressure' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book porepressure refused: porepressure/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run the full pipeline over the well''s sonic and density logs with Eaton n = 3 on the well''s own NCT (656/220/0.0006): density to overburden, hydrostatic, NCT ratio, Eaton pore pressure, and coefficient-form fracture pressure with Poisson''s ratio 0.4. Report the overpressure onset (the first sample more than 0.05 MPa above hydrostatic), the NCT transit time at TD, pore pressure at 3000 m and at TD, the overpressure at TD, and fracture pressure at TD.',
           fields = '[{"key": "onset_m", "tol": 0, "unit": "m bml", "label": "Overpressure onset depth", "expected": 2520}, {"key": "dtn_td", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at TD", "expected": 259.5530276341839}, {"key": "pp_3000_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at 3000 m", "expected": 33.307730125}, {"key": "pp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD", "expected": 47.408579625}, {"key": "op_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overpressure at TD", "expected": 6}, {"key": "fp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Fracture pressure at TD", "expected": 76.55157117548856}]'::jsonb
     where app_slug = 'porepressure' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book porepressure refused: porepressure/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd3429a6bfebb24bbf86b33d7acaea0bd' and fields = '[{"key": "onset_m", "tol": 0, "unit": "m bml", "label": "Overpressure onset depth", "expected": 2520}, {"key": "dtn_td", "tol": 0.5, "unit": "us/m", "label": "NCT transit time at TD", "expected": 259.5530276341839}, {"key": "pp_3000_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at 3000 m", "expected": 33.307730125}, {"key": "pp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD", "expected": 47.408579625}, {"key": "op_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Overpressure at TD", "expected": 6}, {"key": "fp_td_mpa", "tol": 0.01, "unit": "MPa", "label": "Fracture pressure at TD", "expected": 76.55157117548856}]'::jsonb) from public.academy_capstones where app_slug = 'porepressure' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book porepressure refused: porepressure/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Turn the n = 3 prognosis into drilling numbers: equivalent mud weight referenced to sea level (P divided by g times depth-below-mudline plus water depth) for pore and fracture pressure at TD, and the window between them. Cross-check the physics with Bowers (A 10, B 0.75): the loading velocity at 5 MPa effective stress, and the effective stress the unloading form (sigma_max 50 MPa, U 3) reads from 3125.8 m/s. Then probe the calibration lever: pore pressure at TD with Eaton n = 1.2.',
           fields = '[{"key": "pp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Pore pressure as EMW at TD", "expected": 1179.1048116553065}, {"key": "fp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Fracture pressure as EMW at TD", "expected": 1903.9238599165737}, {"key": "window_td", "tol": 0.5, "unit": "kg/m3", "label": "Mud-weight window at TD", "expected": 724.8190482612672}, {"key": "bowers_v_5mpa", "tol": 0.5, "unit": "m/s", "label": "Bowers loading velocity at 5 MPa", "expected": 1949.944709834568}, {"key": "bowers_sigma_mpa", "tol": 0.01, "unit": "MPa", "label": "Bowers unloading stress at 3125.8 m/s", "expected": 10}, {"key": "pp_td_n12_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD with n = 1.2", "expected": 43.901549937778526}]'::jsonb
     where app_slug = 'porepressure' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book porepressure refused: porepressure/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '4e6a35b11d2f999b38595707bcead8dc' and fields = '[{"key": "pp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Pore pressure as EMW at TD", "expected": 1179.1048116553065}, {"key": "fp_emw_td", "tol": 0.5, "unit": "kg/m3", "label": "Fracture pressure as EMW at TD", "expected": 1903.9238599165737}, {"key": "window_td", "tol": 0.5, "unit": "kg/m3", "label": "Mud-weight window at TD", "expected": 724.8190482612672}, {"key": "bowers_v_5mpa", "tol": 0.5, "unit": "m/s", "label": "Bowers loading velocity at 5 MPa", "expected": 1949.944709834568}, {"key": "bowers_sigma_mpa", "tol": 0.01, "unit": "MPa", "label": "Bowers unloading stress at 3125.8 m/s", "expected": 10}, {"key": "pp_td_n12_mpa", "tol": 0.01, "unit": "MPa", "label": "Pore pressure at TD with n = 1.2", "expected": 43.901549937778526}]'::jsonb) from public.academy_capstones where app_slug = 'porepressure' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book porepressure refused: porepressure/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book porepressure: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
